import os
import re
import json
import time
import random
import hashlib
from datetime import datetime
from typing import Optional, Tuple, List, Dict

import pdfplumber
import requests
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.cidfonts import UnicodeCIDFont

# ============================================================
# 0. 配置
#    按你的要求：保留硬编码路径
# ============================================================

INPUT_PDF = r"D:\小说\哈利波特\Harry Potter.pdf"
OUTPUT_PDF = r"D:\小说\哈利波特\Harry Potter_translated.pdf"

# 状态文件也固定放在小说目录
QUOTA_FILE = r"D:\小说\哈利波特\translation_quota.json"
PROGRESS_FILE = r"D:\小说\哈利波特\translation_progress.json"
CACHE_DIR = r"D:\小说\哈利波特\translation_cache"

# 你原来的额度设置
MONTHLY_FREE_QUOTA = 1_000_000

# 百度翻译 API
BAIDU_URL = "https://fanyi-api.baidu.com/api/trans/vip/translate"
SOURCE_LANG = "en"
TARGET_LANG = "zh"

# 每次 API 请求的字符上限。
# 这里故意留安全余量，不建议直接顶到接口极限。
MAX_CHARS_PER_REQUEST = 4_000

# API 重试
MAX_RETRIES = 3
RETRY_BASE_SECONDS = 2

# PDF 排版
FONT_NAME = "STSong-Light"
FONT_SIZE = 11
LINE_HEIGHT = 16
MARGIN = 30
FOOTER_SIZE = 8

# ============================================================
# 1. 初始化
# ============================================================

os.makedirs(CACHE_DIR, exist_ok=True)

pdfmetrics.registerFont(UnicodeCIDFont(FONT_NAME))

try:
    APPID = os.environ["BAIDU_FANYI_APPID"]
    SECRET_KEY = os.environ["BAIDU_FANYI_SECRET"]
except KeyError:
    raise RuntimeError(
        "请先设置环境变量 BAIDU_FANYI_APPID 和 BAIDU_FANYI_SECRET"
    )

# 复用 HTTP 连接
SESSION = requests.Session()

# ============================================================
# 2. JSON 原子写入
# ============================================================

def atomic_write_json(path: str, data: dict) -> None:
    """
    先写临时文件，再原子替换。
    防止程序突然退出导致 JSON 文件写坏。
    """
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)

    temp_path = path + ".tmp"

    with open(temp_path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

    os.replace(temp_path, path)

# ============================================================
# 3. 月度额度管理
# ============================================================

def current_month() -> str:
    return datetime.now().strftime("%Y-%m-01")

def load_quota() -> Dict:
    if not os.path.exists(QUOTA_FILE):
        return {
            "used_chars": 0,
            "last_reset_date": current_month(),
        }

    try:
        with open(QUOTA_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)

        return {
            "used_chars": int(data.get("used_chars", 0)),
            "last_reset_date": data.get(
                "last_reset_date",
                current_month()
            ),
        }

    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        print("⚠️ 额度文件损坏，将重新初始化。")

        return {
            "used_chars": 0,
            "last_reset_date": current_month(),
        }

def save_quota(used_chars: int) -> None:
    atomic_write_json(
        QUOTA_FILE,
        {
            "used_chars": int(used_chars),
            "last_reset_date": current_month(),
        }
    )

def check_and_reset_quota() -> int:
    data = load_quota()
    month = current_month()

    if data["last_reset_date"] != month:
        save_quota(0)
        print("🔄 新月份，程序记录的额度已重置为 100 万字符")
        return 0

    return max(0, data["used_chars"])

def sync_quota_from_cache() -> int:
    """
    启动时根据成功缓存的页面核对额度。

    用于解决：
    API 成功
        ↓
    页面缓存已经保存
        ↓
    电脑突然断电
        ↓
    quota.json 还没来得及保存

    下次运行时可以根据缓存恢复额度记录。
    """
    used = check_and_reset_quota()
    month = current_month()
    cached_cost = 0

    try:
        filenames = os.listdir(CACHE_DIR)
    except OSError:
        return used

    for filename in filenames:
        if not filename.endswith(".json"):
            continue

        path = os.path.join(CACHE_DIR, filename)

        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)

            if (
                data.get("status") == "completed"
                and data.get("usage_month") == month
            ):
                cached_cost += int(data.get("cost_chars", 0))

        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            continue

    corrected = max(used, cached_cost)

    if corrected != used:
        save_quota(corrected)
        print(
            f"🔧 根据缓存校正额度："
            f"{corrected}/{MONTHLY_FREE_QUOTA}"
        )

    return corrected

def check_quota(text_len: int) -> Tuple[bool, int, int]:
    used = check_and_reset_quota()
    remaining = max(0, MONTHLY_FREE_QUOTA - used)

    return remaining >= text_len, used, remaining

def add_used_chars(chars: int) -> int:
    """
    注意：
    这里不要再调用 sync_quota_from_cache()。

    因为当前页缓存已经写入后，
    再从缓存统计一次会把当前页重复计算。
    """
    used = check_and_reset_quota()
    new_used = used + chars

    save_quota(new_used)

    return new_used

# ============================================================
# 4. 断点进度管理
# ============================================================

def load_progress() -> Dict:
    if not os.path.exists(PROGRESS_FILE):
        return {
            "last_finished_page": 0,
            "total_pages": None,
            "input_pdf": INPUT_PDF,
        }

    try:
        with open(PROGRESS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)

        return {
            "last_finished_page": int(
                data.get("last_finished_page", 0)
            ),
            "total_pages": data.get("total_pages"),
            "input_pdf": data.get("input_pdf", INPUT_PDF),
        }

    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return {
            "last_finished_page": 0,
            "total_pages": None,
            "input_pdf": INPUT_PDF,
        }

def save_progress(
    last_finished_page: int,
    total_pages: int
) -> None:

    atomic_write_json(
        PROGRESS_FILE,
        {
            "last_finished_page": int(last_finished_page),
            "total_pages": int(total_pages),
            "input_pdf": INPUT_PDF,
            "updated_at": datetime.now().isoformat(
                timespec="seconds"
            ),
        }
    )

def clear_progress() -> None:
    try:
        if os.path.exists(PROGRESS_FILE):
            os.remove(PROGRESS_FILE)
    except OSError:
        pass

# ============================================================
# 5. 页面缓存
# ============================================================

def page_cache_path(page_num: int) -> str:
    return os.path.join(
        CACHE_DIR,
        f"page_{page_num:04d}.json"
    )

def text_hash(text: str) -> str:
    return hashlib.sha256(
        text.encode("utf-8")
    ).hexdigest()

def load_page_cache(
    page_num: int,
    source_text: str
) -> Optional[Dict]:

    path = page_cache_path(page_num)

    if not os.path.exists(path):
        return None

    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)

        if data.get("status") != "completed":
            return None

        # 防止换了 PDF 后错误使用旧缓存
        if data.get("source_hash") != text_hash(source_text):
            return None

        if "translated_text" not in data:
            return None

        return data

    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return None

def save_page_cache(
    page_num: int,
    source_text: str,
    translated_text: str,
    cost_chars: int
) -> None:

    data = {
        "status": "completed",
        "page_num": page_num,
        "source_hash": text_hash(source_text),
        "input_chars": len(source_text),
        "cost_chars": int(cost_chars),
        "translated_text": translated_text,
        "usage_month": current_month(),
        "completed_at": datetime.now().isoformat(
            timespec="seconds"
        ),
    }

    atomic_write_json(
        page_cache_path(page_num),
        data
    )

# ============================================================
# 6. 文本清洗
# ============================================================

def normalize_text(text: str) -> str:
    if not text:
        return ""

    text = text.replace("\r\n", "\n")
    text = text.replace("\r", "\n")

    # 压缩连续空格
    lines = []

    for line in text.split("\n"):
        line = re.sub(r"[ \t]+", " ", line).strip()
        lines.append(line)

    # 最多保留一个连续空行
    cleaned = []
    blank_count = 0

    for line in lines:

        if line:
            cleaned.append(line)
            blank_count = 0

        else:
            blank_count += 1

            if blank_count <= 1:
                cleaned.append("")

    return "\n".join(cleaned).strip()

# ============================================================
# 7. 英文文本智能分块
# ============================================================

ABBREVIATIONS = [
    "Mr.",
    "Mrs.",
    "Ms.",
    "Dr.",
    "Prof.",
    "St.",
    "Jr.",
    "Sr.",
    "Inc.",
    "Ltd.",
    "e.g.",
    "i.e.",
    "vs.",
    "No.",
    "Fig.",
]

def protect_abbreviations(text: str) -> str:

    for abbr in ABBREVIATIONS:
        protected = abbr.replace(".", "<DOT>")
        text = text.replace(abbr, protected)

    return text

def restore_abbreviations(text: str) -> str:
    return text.replace("<DOT>", ".")

def split_long_piece(
    text: str,
    max_len: int
) -> List[str]:
    """
    单个句子本身超过 API 长度时：
    优先按空格切；
    连续无空格时最后才硬切。
    """
    text = text.strip()

    if not text:
        return []

    if len(text) <= max_len:
        return [text]

    pieces = []
    current = ""

    tokens = re.split(r"(\s+)", text)

    for token in tokens:

        if not token:
            continue

        if len(current) + len(token) <= max_len:
            current += token
            continue

        if current.strip():
            pieces.append(current.strip())

        current = ""

        # 当前 token 自身就超过限制
        while len(token) > max_len:
            pieces.append(token[:max_len])
            token = token[max_len:]

        current = token

    if current.strip():
        pieces.append(current.strip())

    return pieces

def split_paragraph(
    paragraph: str,
    max_len: int
) -> List[str]:

    protected = protect_abbreviations(paragraph)

    # 尽量按照句号、问号、感叹号分句
    sentences = re.split(
        r'(?<=[.!?]["\')\]”’]?)'
        r'\s+'
        r'(?=[A-Z0-9“"\'(])',
        protected
    )

    sentences = [
        restore_abbreviations(sentence).strip()
        for sentence in sentences
        if sentence.strip()
    ]

    chunks = []
    current = ""

    for sentence in sentences:

        pieces = split_long_piece(
            sentence,
            max_len
        )

        for piece in pieces:

            if len(current) + len(piece) + 1 <= max_len:

                current = (
                    f"{current} {piece}"
                ).strip()

            else:

                if current:
                    chunks.append(current)

                current = piece

    if current:
        chunks.append(current)

    return chunks

def split_text(
    text: str,
    max_len: int = MAX_CHARS_PER_REQUEST
) -> List[str]:

    text = normalize_text(text)

    if not text:
        return []

    if len(text) <= max_len:
        return [text]

    blocks = []

    # 双换行作为段落边界
    paragraphs = re.split(
        r"\n\s*\n",
        text
    )

    for paragraph in paragraphs:

        paragraph = paragraph.strip()

        if not paragraph:
            continue

        paragraph_blocks = split_paragraph(
            paragraph,
            max_len
        )

        for block in paragraph_blocks:

            if len(block) <= max_len:
                blocks.append(block)

            else:
                blocks.extend(
                    split_long_piece(
                        block,
                        max_len
                    )
                )

    return blocks

# ============================================================
# 8. 百度翻译 API
# ============================================================

def baidu_translate_block(
    q: str
) -> Tuple[str, int]:

    q = q.strip()

    if not q:
        return "", 0

    salt = str(
        random.randint(1, 10000)
    )

    sign = hashlib.md5(
        (
            APPID
            + q
            + salt
            + SECRET_KEY
        ).encode("utf-8")
    ).hexdigest()

    last_error = None

    for attempt in range(
        1,
        MAX_RETRIES + 1
    ):

        try:

            response = SESSION.post(
                BAIDU_URL,
                data={
                    "q": q,
                    "from": SOURCE_LANG,
                    "to": TARGET_LANG,
                    "appid": APPID,
                    "salt": salt,
                    "sign": sign,
                },
                timeout=(10, 30),
            )

            response.raise_for_status()

            try:
                result = response.json()

            except ValueError as e:
                raise RuntimeError(
                    "百度 API 返回的不是合法 JSON"
                ) from e

            if "trans_result" in result:

                translated_parts = []

                for item in result["trans_result"]:

                    dst = item.get("dst")

                    if dst is not None:
                        translated_parts.append(dst)

                translated = "\n".join(
                    translated_parts
                ).strip()

                return translated, len(q)

            error_code = result.get(
                "error_code",
                "未知"
            )

            error_msg = result.get(
                "error_msg",
                ""
            )

            raise RuntimeError(
                f"百度 API 失败："
                f"error_code={error_code}, "
                f"error_msg={error_msg}"
            )

        except (
            requests.RequestException,
            RuntimeError
        ) as e:

            last_error = e

            if attempt < MAX_RETRIES:

                wait_seconds = (
                    RETRY_BASE_SECONDS ** attempt
                )

                print(
                    f"   ⚠️ API 请求失败，"
                    f"第 {attempt}/{MAX_RETRIES} 次重试"
                )

                print(
                    f"   {e}"
                )

                time.sleep(
                    wait_seconds
                )

            else:
                break

    raise RuntimeError(
        f"连续 {MAX_RETRIES} 次失败："
        f"{last_error}"
    )

def baidu_translate(
    text: str
) -> Tuple[str, int]:

    text = normalize_text(text)

    if not text:
        return "", 0

    enough, used, remaining = check_quota(
        len(text)
    )

    if not enough:

        raise RuntimeError(
            f"本月额度不足："
            f"已用 {used}/{MONTHLY_FREE_QUOTA}，"
            f"剩余 {remaining}，"
            f"本页需要约 {len(text)} 字符。"
        )

    blocks = split_text(text)

    if not blocks:
        return "", 0

    results = []
    total_cost = 0

    for index, block in enumerate(
        blocks,
        start=1
    ):

        print(
            f"   API 请求 "
            f"{index}/{len(blocks)}，"
            f"本块 {len(block)} 字符"
        )

        translated, cost = (
            baidu_translate_block(
                block
            )
        )

        results.append(translated)
        total_cost += cost

        # 稍微降低连续请求过快的风险
        if index < len(blocks):
            time.sleep(0.3)

    translated_text = "\n\n".join(
        x for x in results
        if x.strip()
    )

    return translated_text, total_cost

# ============================================================
# 9. 中文/英文混排自动换行
# ============================================================

def wrap_text_to_lines(
    text: str,
    max_width: float,
    font_name: str,
    font_size: float
) -> List[str]:

    lines = []

    # 保留原有换行
    for paragraph in text.split("\n"):

        paragraph = paragraph.strip()

        if not paragraph:
            lines.append("")
            continue

        current = ""
        last_space_pos = -1

        for ch in paragraph:

            test = current + ch

            if pdfmetrics.stringWidth(
                test,
                font_name,
                font_size
            ) <= max_width:

                current = test

                if ch.isspace():
                    last_space_pos = (
                        len(current) - 1
                    )

                continue

            # 当前行已经超宽
            if current.strip():

                # 如果是英文，优先在最近空格处换行
                if last_space_pos > 0:

                    line = (
                        current[:last_space_pos]
                        .rstrip()
                    )

                    remainder = (
                        current[last_space_pos + 1:]
                        + ch
                    )

                    lines.append(line)

                    current = (
                        remainder
                        .lstrip()
                    )

                else:

                    lines.append(
                        current.rstrip()
                    )

                    current = ch

            else:

                current = ch

            last_space_pos = (
                len(current) - 1
                if current
                and current[-1].isspace()
                else -1
            )

        if current.strip():
            lines.append(
                current.rstrip()
            )

    return lines

# ============================================================
# 10. 页脚
# ============================================================

def draw_footer(
    c,
    page_width: float,
    source_page_num: int,
    continued: bool
):

    footer = (
        f"原 PDF 第 {source_page_num} 页"
    )

    if continued:
        footer += "（续）"

    c.setFont(
        FONT_NAME,
        FOOTER_SIZE
    )

    c.drawCentredString(
        page_width / 2,
        12,
        footer
    )

# ============================================================
# 11. 从缓存重建 PDF
# ============================================================

def rebuild_output_pdf(
    input_pdf: str
) -> None:

    print("\n📄 正在从翻译缓存生成 PDF...")

    with pdfplumber.open(input_pdf) as pdf:

        c = canvas.Canvas(
            OUTPUT_PDF
        )

        completed_pages = 0

        for idx, page in enumerate(
            pdf.pages,
            start=1
        ):

            source_text = normalize_text(
                page.extract_text() or ""
            )

            cache = load_page_cache(
                idx,
                source_text
            )

            # 一旦出现缺失页，就停止。
            # 避免 1、2、3、5 页都有，4 页没有时，
            # 输出 PDF 出现页码错乱。
            if cache is None:
                print(
                    f"   ⏹ PDF 重建到第 "
                    f"{idx - 1} 页停止"
                )
                break

            translated_text = (
                cache.get(
                    "translated_text",
                    ""
                ).strip()
            )

            # 空白页
            if not translated_text:

                c.setPageSize(
                    (page.width, page.height)
                )

                draw_footer(
                    c,
                    page.width,
                    idx,
                    False
                )

                c.showPage()

                completed_pages += 1
                continue

            c.setPageSize(
                (page.width, page.height)
            )

            max_width = (
                page.width
                - 2 * MARGIN
            )

            y = (
                page.height
                - MARGIN
            )

            lines = wrap_text_to_lines(
                translated_text,
                max_width,
                FONT_NAME,
                FONT_SIZE
            )

            continued = False

            for line in lines:

                if y < (
                    MARGIN
                    + FOOTER_SIZE
                    + 10
                ):

                    draw_footer(
                        c,
                        page.width,
                        idx,
                        continued
                    )

                    c.showPage()

                    c.setPageSize(
                        (
                            page.width,
                            page.height
                        )
                    )

                    c.setFont(
                        FONT_NAME,
                        FONT_SIZE
                    )

                    y = (
                        page.height
                        - MARGIN
                    )

                    continued = True

                if line == "":
                    y -= LINE_HEIGHT
                    continue

                c.setFont(
                    FONT_NAME,
                    FONT_SIZE
                )

                c.drawString(
                    MARGIN,
                    y,
                    line
                )

                y -= LINE_HEIGHT

            draw_footer(
                c,
                page.width,
                idx,
                continued
            )

            c.showPage()

            completed_pages += 1

        c.save()

    print(
        f"✅ PDF 已保存：{OUTPUT_PDF}"
    )

    print(
        f"📄 已写入 {completed_pages} 个原 PDF 页面"
    )

# ============================================================
# 12. 主翻译流程
# ============================================================

def translate_pdf_resumable(
    input_pdf: str
) -> None:

    if not os.path.exists(input_pdf):
        raise FileNotFoundError(
            f"找不到输入 PDF：{input_pdf}"
        )

    # 程序启动时先根据缓存校正一次额度
    current_used = sync_quota_from_cache()

    progress = load_progress()

    print("=" * 65)
    print("📚 PDF 自动翻译程序")
    print("=" * 65)
    print(f"输入文件：{input_pdf}")
