# ============================================================
# 3. 月度额度管理
# ============================================================

def current_month() -> str:
    return datetime.now().strftime("%Y-%m-01")

def load_quota() -> Dict:
    if not os.path.exists(QUOTA_FILE):
        return {
            "used_chars": 0,
            "last_reset_date": current_month()
        }

    try:
        with open(
            QUOTA_FILE,
            "r",
            encoding="utf-8"
        ) as f:
            data = json.load(f)

        return {
            "used_chars": int(
                data.get("used_chars", 0)
            ),
            "last_reset_date": data.get(
                "last_reset_date",
                current_month()
            )
        }

    except (
        OSError,
        ValueError,
        TypeError,
        json.JSONDecodeError
    ):
        print("⚠️ 额度文件损坏，将重新初始化。")

        return {
            "used_chars": 0,
            "last_reset_date": current_month()
        }

def save_quota(used_chars: int) -> None:
    atomic_write_json(
        QUOTA_FILE,
        {
            "used_chars": int(used_chars),
            "last_reset_date": current_month()
        }
    )

def check_and_reset_quota() -> int:
    data = load_quota()
    month = current_month()

    if data["last_reset_date"] != month:
        save_quota(0)

        print(
            "🔄 新月份，"
            "程序记录的额度已重置为 100 万字符"
        )

        return 0

    return max(
        0,
        data["used_chars"]
    )

def sync_quota_from_cache() -> int:
    """
    根据成功缓存的页面核对额度。

    用于防止：
    API 成功
        ↓
    页面缓存保存成功
        ↓
    程序突然退出
        ↓
    quota.json 尚未来得及更新
    """

    used = check_and_reset_quota()
    month = current_month()
    cached_cost = 0

    try:
        filenames = os.listdir(
            CACHE_DIR
        )
    except OSError:
        return used

    for filename in filenames:

        if not filename.endswith(".json"):
            continue

        path = os.path.join(
            CACHE_DIR,
            filename
        )

        try:
            with open(
                path,
                "r",
                encoding="utf-8"
            ) as f:
                data = json.load(f)

            if (
                data.get("status") == "completed"
                and data.get("usage_month") == month
            ):
                cached_cost += int(
                    data.get("cost_chars", 0)
                )

        except (
            OSError,
            ValueError,
            TypeError,
            json.JSONDecodeError
        ):
            continue

    corrected = max(
        used,
        cached_cost
    )

    if corrected != used:

        save_quota(corrected)

        print(
            f"🔧 根据缓存校正额度："
            f"{corrected}/{MONTHLY_FREE_QUOTA}"
        )

    return corrected

def check_quota(
    text_len: int
) -> Tuple[bool, int, int]:

    used = check_and_reset_quota()

    remaining = max(
        0,
        MONTHLY_FREE_QUOTA - used
    )

    return (
        remaining >= text_len,
        used,
        remaining
    )

def add_used_chars(
    chars: int
