def page_cache_path(
    page_num: int
) -> str:

    return os.path.join(
        CACHE_DIR,
        f"page_{page_num:04d}.json"
    )

def text_hash(
    text: str
) -> str:

    return hashlib.sha256(
        text.encode("utf-8")
    ).hexdigest()

def load_page_cache(
    page_num: int,
    source_text: str
) -> Optional[Dict]:

    path = page_cache_path(
        page_num
    )

    if not os.path.exists(path):
        return None

    try:

        with open(
            path,
            "r",
            encoding="utf-8"
        ) as f:
            data = json.load(f)

        if data.get("status") != "completed":
            return None

        # 防止换 PDF 后误用旧缓存
        if (
            data.get("source_hash")
            != text_hash(source_text)
        ):
            return None

        if "translated_text" not in data:
            return None

        return data

    except (
        OSError,
        ValueError,
        TypeError,
        json.JSONDecodeError
    ):

        return None

