    page_num: int,
    source_text: str,
    translated_text: str,
    cost_chars: int
) -> None:

    data = {
        "status": "completed",
        "page_num": page_num,

        "source_hash":
            text_hash(source_text),

        "input_chars":
            len(source_text),

        "cost_chars":
            int(cost_chars),

        "translated_text":
            translated_text,

        "usage_month":
            current_month(),

        "completed_at":
            datetime.now().isoformat(
                timespec="seconds"
