    )

# ============================================================
# 6. 文本清洗
# ============================================================

def normalize_text(
    text: str
) -> str:

    if not text:
        return ""

    text = text.replace(
        "\r\n",
        "\n"
    )

    text = text.replace(
        "\r",
        "\n"
    )

    lines = []

    for line in text.split("\n"):

        line = re.sub(
            r"[ \t]+",
            " ",
            line
        ).strip()

        lines.append(line)

    cleaned = []
    blank_count = 0

    for line in lines:

        if line:

            cleaned.append(line)
            blank_count = 0

        else:

            blank_count += 1

            if blank_count <= 1:
                cleaned.append("")

    return "\n".join(
        cleaned
    ).strip()

# ============================================================
# 7. 英文文本智能分块
# ============================================================

ABBREVIATIONS = [
    "Mr.",
    "Mrs.",
    "Ms.",
    "Dr.",
    "Prof.",
    "St.",
    "Jr.",
    "Sr.",
    "Inc.",
    "Ltd.",
    "e.g.",
    "i.e.",
    "vs.",
    "No.",
    "Fig."
]

def protect_abbreviations(
    text: str
) -> str:

    for abbr in ABBREVIATIONS:

        protected = abbr.replace(
            ".",
            "<DOT>"
        )

        text = text.replace(
            abbr,
            protected
        )

    return text

def restore_abbreviations(
    text: str
) -> str:

    return text.replace(
        "<DOT>",
        "."
    )

def split_long_piece(
    text: str,
    max_len: int
) -> List[str]:

    text = text.strip()

    if not text:
        return []

    if len(text) <= max_len:
        return [text]

    pieces = []
    current = ""

    tokens = re.split(
        r"(\s+)",
        text
    )

    for token in tokens:

        if not token:
            continue

        if (
            len(current)
            + len(token)
            <= max_len
        ):

            current += token
            continue

        if current.strip():
            pieces.append(
                current.strip()
            )

        current = ""

        # 如果 token 本身超过限制
        while len(token) > max_len:

            pieces.append(
                token[:max_len]
            )

            token = token[max_len:]

        current = token

    if current.strip():

        pieces.append(
            current.strip()
        )

    return pieces

def split_paragraph(
    paragraph: str,
    max_len: int
) -> List[str]:

    protected = protect_abbreviations(
        paragraph
    )

    sentences = re.split(
        r'(?<=[.!?]["\')\]”’]?)'
        r'\s+'
        r'(?=[A-Z0-9“"\'(])',
        protected
    )

    sentences = [
        restore_abbreviations(
            sentence
        ).strip()

        for sentence in sentences

        if sentence.strip()
    ]

    chunks = []
    current = ""

    for sentence in sentences:

        pieces = split_long_piece(
            sentence,
            max_len
        )

        for piece in pieces:

            if (
                len(current)
                + len(piece)
                + 1
                <= max_len
            ):

                current = (
                    f"{current} {piece}"
                ).strip()

            else:

                if current:
                    chunks.append(
                        current
                    )

                current = piece

    if current:
        chunks.append(
            current
        )

    return chunks

def split_text(
    text: str,
    max_len: int = MAX_CHARS_PER_REQUEST
) -> List[str]:

    text = normalize_text(text)

    if not text:
        return []

    if len(text) <= max_len:
        return [text]

    blocks = []

    paragraphs = re.split(
        r"\n\s*\n",
        text
    )

    for paragraph in paragraphs:

        paragraph = paragraph.strip()

        if not paragraph:
            continue

        paragraph_blocks = split_paragraph(
            paragraph,
            max_len
        )

        for block in paragraph_blocks:

            if len(block) <= max_len:

                blocks.append(
                    block
                )

            else:

                blocks.extend(
                    split_long_piece(
                        block,
                        max_len
                    )
                )

    return blocks

# ============================================================
# 8. 百度翻译 API
# ============================================================

def baidu_translate_block(
    q: str
) -> Tuple[str, int]:

    q = q.strip()

    if not q:
        return "", 0

    salt = str(
        random.randint(
            1,
            10000
        )
    )

    sign = hashlib.md5(
        (
            APPID
            + q
            + salt
            + SECRET_KEY
        ).encode("utf-8")
    ).hexdigest()

    last_error = None

    for attempt in range(
        1,
        MAX_RETRIES + 1
    ):

        try:

            response = SESSION.post(
                BAIDU_URL,

                data={
                    "q": q,
                    "from": SOURCE_LANG,
                    "to": TARGET_LANG,
                    "appid": APPID,
                    "salt": salt,
                    "sign": sign
                },

                timeout=(
                    10,
                    30
                )
            )

            response.raise_for_status()

            try:

                result = response.json()

            except ValueError as e:

                raise RuntimeError(
                    "百度 API 返回的不是合法 JSON"
                ) from e

            if "trans_result" in result:

                translated_parts = []

                for item in result[
                    "trans_result"
                ]:

                    dst = item.get(
                        "dst"
                    )

                    if dst is not None:

                        translated_parts.append(
                            dst
                        )

                translated = "\n".join(
                    translated_parts
                ).strip()

                return (
                    translated,
                    len(q)
                )

            error_code = result.get(
                "error_code",
                "未知"
            )

            error_msg = result.get(
                "error_msg",
                ""
            )

            raise RuntimeError(
                f"百度 API 失败："
                f"error_code={error_code}, "
                f"error_msg={error_msg}"
            )

        except (
            requests.RequestException,
            RuntimeError
        ) as e:

            last_error = e

            if attempt < MAX_RETRIES:

                wait_seconds = (
                    RETRY_BASE_SECONDS
                    ** attempt
                )

                print(
                    f"   ⚠️ API 请求失败，"
                    f"第 {attempt}/{MAX_RETRIES} 次重试"
                )

                print(
                    f"   {e}"
                )

                time.sleep(
                    wait_seconds
                )

            else:
                break

    raise RuntimeError(
        f"连续 {MAX_RETRIES} 次失败："
        f"{last_error}"
    )

def baidu_translate(
    text: str
) -> Tuple[str, int]:

    text = normalize_text(text)

    if not text:
        return "", 0

    enough, used, remaining = (
        check_quota(
            len(text)
        )
    )

    if not enough:

        raise RuntimeError(
            f"本月额度不足："
            f"已用 {used}/{MONTHLY_FREE_QUOTA}，"
            f"剩余 {remaining}，"
            f"本页需要约 {len(text)} 字符。"
        )

    blocks = split_text(text)

    if not blocks:
        return "", 0

    results = []
    total_cost = 0

    for index, block in enumerate(
        blocks,
        start=1
    ):

        print(
            f"   API 请求 "
            f"{index}/{len(blocks)}，"
            f"本块 {len(block)} 字符"
        )

        translated, cost = (
            baidu_translate_block(
                block
            )
        )

        results.append(
            translated
        )

        total_cost += cost

        if index < len(blocks):
            time.sleep(0.3)

    translated_text = "\n\n".join(
        x
        for x in results
        if x.strip()
    )

    return (
        translated_text,
        total_cost
    )

# ============================================================
# 9. 自动换行
# ============================================================

def wrap_text_to_lines(
    text: str,
    max_width: float,
    font_name: str,
    font_size: float
) -> List[str]:

    lines = []

    for paragraph in text.split(
        "\n"
    ):

        paragraph = paragraph.strip()

        if not paragraph:

            lines.append("")
            continue

        current = ""
        last_space_pos = -1

        for ch in paragraph:

            test = current + ch

            if (
                pdfmetrics.stringWidth(
                    test,
                    font_name,
                    font_size
                )
                <= max_width
            ):

                current = test

                if ch.isspace():

                    last_space_pos = (
                        len(current) - 1
                    )

                continue

            if current.strip():

                # 英文优先在空格处换行
                if last_space_pos > 0:

                    line = (
                        current[
                            :last_space_pos
                        ].rstrip()
                    )

                    remainder = (
                        current[
                            last_space_pos + 1:
                        ]
                        + ch
                    )

                    lines.append(
                        line
                    )

                    current = (
                        remainder.lstrip()
                    )

                else:

                    lines.append(
                        current.rstrip()
                    )

                    current = ch

            else:

                current = ch

            last_space_pos = (
                len(current) - 1
                if current
                and current[-1].isspace()
                else -1
            )

        if current.strip():

            lines.append(
                current.rstrip()
            )

    return lines

# ============================================================
# 10. 页脚
# ============================================================

def draw_footer(
    c,
    page_width: float,
    source_page_num: int,
    continued: bool
):

    footer = (
        f"原 PDF 第 {source_page_num} 页"
    )

    if continued:
        footer += "（续）"

    c.setFont(
        FONT_NAME,
        FOOTER_SIZE
    )

    c.drawCentredString(
        page_width / 2,
        12,
        footer
    )

# ============================================================
# 11. 根据缓存重建 PDF
# ============================================================

def rebuild_output_pdf(
    input_pdf: str
) -> None:

    print(
        "\n📄 正在从翻译缓存生成 PDF..."
    )

    with pdfplumber.open(
        input_pdf
    ) as pdf:

        c = canvas.Canvas(
            OUTPUT_PDF
        )

        completed_pages = 0

        for idx, page in enumerate(
            pdf.pages,
            start=1
        ):

            source_text = normalize_text(
                page.extract_text() or ""
            )

            cache = load_page_cache(
                idx,
                source_text
            )

            # 如果出现缺失页，
            # 停止生成后续页面
            if cache is None:

                print(
                    f"   ⏹ PDF 重建到第 "
                    f"{idx - 1} 页停止"
                )

                break

            translated_text = (
                cache.get(
                    "translated_text",
                    ""
                ).strip()
            )

            # 空白页
            if not translated_text:

                c.setPageSize(
                    (
                        page.width,
                        page.height
                    )
                )

                draw_footer(
                    c,
                    page.width,
                    idx,
                    False
                )

                c.showPage()

                completed_pages += 1

                continue

            c.setPageSize(
                (
                    page.width,
                    page.height
                )
            )

            max_width = (
                page.width
                - 2 * MARGIN
            )

            y = (
                page.height
                - MARGIN
            )

            lines = wrap_text_to_lines(
                translated_text,
                max_width,
                FONT_NAME,
                FONT_SIZE
            )

            continued = False

            for line in lines:

                if y < (
                    MARGIN
                    + FOOTER_SIZE
                    + 10
                ):

                    draw_footer(
                        c,
                        page.width,
                        idx,
                        continued
                    )

                    c.showPage()

                    c.setPageSize(
                        (
                            page.width,
                            page.height
                        )
                    )

                    c.setFont(
                        FONT_NAME,
                        FONT_SIZE
                    )

                    y = (
                        page.height
                        - MARGIN
                    )

                    continued = True

                if line == "":

                    y -= LINE_HEIGHT
                    continue

                c.setFont(
                    FONT_NAME,
                    FONT_SIZE
                )

                c.drawString(
                    MARGIN,
                    y,
                    line
                )

                y -= LINE_HEIGHT

            draw_footer(
                c,
                page.width,
                idx,
                continued
            )

            c.showPage()

            completed_pages += 1

        c.save()

    print(
        f"✅ PDF 已保存：{OUTPUT_PDF}"
    )

    print(
        f"📄 已写入 {completed_pages} 个原 PDF 页面"
    )

# ============================================================
# 12. 主翻译流程
# ============================================================

def translate_pdf_resumable(
    input_pdf: str
) -> None:

    if not os.path.exists(
        input_pdf
    ):

        raise FileNotFoundError(
            f"找不到输入 PDF：{input_pdf}"
        )

    # 启动时校正额度
    current_used = (
        sync_quota_from_cache()
    )

    progress = load_progress()

    print("=" * 65)
    print("📚 PDF 自动翻译程序")
    print("=" * 65)

    print(
        f"输入文件：{input_pdf}"
    )

    print(
        f"输出文件：{OUTPUT_PDF}"
    )

    print(
        f"缓存目录：{CACHE_DIR}"
    )

    print(
        f"当前额度："
        f"{current_used}/"
        f"{MONTHLY_FREE_QUOTA}"
    )

    print(
        f"上次完成页："
        f"{progress.get('last_finished_page', 0)}"
    )

    print("=" * 65)

    with pdfplumber.open(
        input_pdf
    ) as pdf:

        total_pages = len(
            pdf.pages
        )

        print(
            f"📖 PDF 总页数："
            f"{total_pages}"
        )

        last_finished_page = (
            progress.get(
                "last_finished_page",
                0
            )
        )

        for idx, page in enumerate(
            pdf.pages,
            start=1
        ):

            print(
                f"\n========== "
                f"第 {idx}/{total_pages} 页 "
                f"=========="
            )

            # ------------------------------------------------
            # A. 提取文字
            # ------------------------------------------------

            try:

                source_text = normalize_text(
                    page.extract_text() or ""
                )

            except Exception as e:

                print(
                    f"❌ 第 {idx} 页文本提取失败：{e}"
                )

                print(
                    "   当前页不会被标记为完成。"
                )

                rebuild_output_pdf(
                    input_pdf
                )

                save_progress(
                    last_finished_page,
                    total_pages
                )

                return

            # ------------------------------------------------
            # B. 检查缓存
            # ------------------------------------------------

            cached = load_page_cache(
                idx,
                source_text
            )

            if cached is not None:

                print(
                    "♻️ 发现有效缓存，"
                    "跳过 API 翻译。"
                )

                last_finished_page = idx

                save_progress(
                    last_finished_page,
                    total_pages
                )

                continue

            # ------------------------------------------------
            # C. 空白页
            # ------------------------------------------------

            if not source_text:

                print(
                    "📄 本页没有可提取文字，"
                    "记为空白页。"
                )

                save_page_cache(
                    page_num=idx,
                    source_text="",
                    translated_text="",
                    cost_chars=0
                )

                last_finished_page = idx

                save_progress(
                    last_finished_page,
                    total_pages
                )

                continue

            # ------------------------------------------------
            # D. 检查额度
            # ------------------------------------------------

            enough, used, remaining = (
                check_quota(
                    len(source_text)
                )
            )

            print(
                f"本页字符数："
                f"{len(source_text)}"
            )

            print(
                f"本月已用："
                f"{used}/"
                f"{MONTHLY_FREE_QUOTA}"
            )

            print(
                f"本月剩余："
                f"{remaining}"
            )

            if not enough:

                print(
                    "\n⛔ 本月额度不足，"
                    "停止翻译。"
                )

                print(
                    f"✅ 已成功完成到第 "
                    f"{last_finished_page} 页"
                )

                rebuild_output_pdf(
                    input_pdf
                )

                save_progress(
                    last_finished_page,
                    total_pages
                )

                return

            # ------------------------------------------------
            # E. 翻译
            # ------------------------------------------------

            try:

                translated_text, cost = (
                    baidu_translate(
                        source_text
                    )
                )

            except Exception as e:

                print(
                    f"\n❌ 第 {idx} 页翻译失败："
                    f"{e}"
                )

                print(
                    "⚠️ 当前页不会建立完成缓存。"
                )

                print(
                    "   下次运行会自动重新翻译这一页。"
                )

                rebuild_output_pdf(
                    input_pdf
                )

                save_progress(
                    last_finished_page,
                    total_pages
                )

                return

            # ------------------------------------------------
            # F. 保存页面缓存
            # ------------------------------------------------

            save_page_cache(
                page_num=idx,
                source_text=source_text,
                translated_text=translated_text,
                cost_chars=cost
            )

            print(
                f"💾 第 {idx} 页翻译结果已保存到缓存"
            )

            # ------------------------------------------------
            # G. 更新额度
            # ------------------------------------------------

            if cost > 0:

                new_used = add_used_chars(
                    cost
                )

                print(
                    f"📊 当前额度："
                    f"{new_used}/"
                    f"{MONTHLY_FREE_QUOTA}"
                )

            # ------------------------------------------------
            # H. 更新进度
            # ------------------------------------------------

            last_finished_page = idx

            save_progress(
                last_finished_page,
                total_pages
            )

            print(
                f"✅ 第 {idx} 页完成"
            )

        # ====================================================
        # I. 检查是否全部完成
        # ====================================================

        print(
            "\n🔍 正在检查是否所有页面都有有效缓存..."
        )

        all_completed = True

        for idx, page in enumerate(
            pdf.pages,
            start=1
        ):

            source_text = normalize_text(
                page.extract_text() or ""
            )

            if load_page_cache(
                idx,
                source_text
            ) is None:

                all_completed = False

                print(
                    f"⚠️ 第 {idx} 页没有有效缓存"
                )

                break

        # ====================================================
        # J. 生成 PDF
        # ====================================================

        rebuild_output_pdf(
            input_pdf
        )

        if all_completed:

            clear_progress()

            print(
                "\n" + "=" * 65
            )

            print(
                "🎉 全书翻译完成！"
            )

            print(
                "=" * 65
            )

            print(
                f"📄 输出：{OUTPUT_PDF}"
            )

            print(
                f"📦 缓存：{CACHE_DIR}"
            )

        else:

            print(
                "\n⚠️ 当前还没有全部完成。"
            )

            print(
                "   下次运行时会自动跳过"
                "已经完成的页面。"
            )

# ============================================================
# 13. 运行
# ============================================================

if __name__ == "__main__":

    try:

        translate_pdf_resumable(
            INPUT_PDF
        )

    except KeyboardInterrupt:

        print(
            "\n\n🛑 检测到手动中断。"
        )

        print(
            "正在根据已经完成的缓存生成 PDF..."
        )

        try:

            rebuild_output_pdf(
                INPUT_PDF
            )

            print(
                "✅ 已保存当前已完成内容。"
            )

        except Exception as e:

            print(
                f"⚠️ PDF 保存失败：{e}"
            )

    except Exception as e:

        print(
            f"\n❌ 程序发生未处理异常：{e}"
        )

        try:

            rebuild_output_pdf(
                INPUT_PDF
            )

            print(
                "✅ 已根据缓存保存当前已完成内容。"
            )

        except Exception as pdf_error:

            print(
                f"⚠️ 无法重建 PDF：{pdf_error}"
            )

        raise
